package com.cooker.shopping;

import static org.assertj.core.api.Assertions.*;
import com.cooker.shopping.config.MockCatalogProperties;
import com.cooker.shopping.dto.ProductMatchRequest;
import com.cooker.shopping.provider.*;
import com.cooker.shopping.provider.ProductProvider.*;
import com.cooker.shopping.service.ProductMatchCalculator;
import com.cooker.shopping.vo.ShoppingView;
import java.math.BigDecimal;
import java.util.*;
import org.junit.jupiter.api.Test;

class ProductMatchingTest {
    private BigDecimal n(String value){return value==null?null:new BigDecimal(value);}
    private Product p(String id,String quantity,String unit,String price,boolean stock,String city,String reference){return new Product(id,1L,"Mock葱",List.of(city),stock,n(quantity),unit,n(price),"CNY",n(reference),reference==null?null:"G");}
    private MockProductProvider provider(Product...products){var config=new MockCatalogProperties();config.setCatalogVersion("test-v1");config.setProducts(List.of(products));return new MockProductProvider(config);}
    private ShoppingView.Item item(String key,String quantity,String status,String unit,Long ingredient){return new ShoppingView.Item(key,List.of(key),ingredient==null?null:ingredient.toString(),"原料",unit,unit,false,quantity,"HAVE_ENOUGH".equals(status)?"0":quantity,status,null);}
    private ShoppingView source(String budget,ShoppingView.Item...items){return new ShoppingView(1,"1","test","CURRENT",new ShoppingView.Source("1","2",1,"3",3,budget,"a".repeat(64)),List.of(),List.of(items),"READY_FOR_MATCHING","NOT_MATCHED",null);}
    @Test void 单价精确优先然后整包支出及商品ID且同维换算(){
        var need=new Need("a",1,n("60"),"G");
        assertThat(provider(p("a","100","G","10",true,"110000",null),p("z","0.06","KG","6",true,"110000",null)).lookup("110000",List.of(need)).selections().getFirst().product().productId()).isEqualTo("z");
        assertThat(provider(p("b","100","G","10",true,"110000",null),p("a","100","G","10",true,"110000",null)).lookup("110000",List.of(need)).selections().getFirst().product().productId()).isEqualTo("a");
        assertThat(provider(p("z","100","G","9",true,"110000",null),p("a","100","G","10",true,"110000",null)).lookup("110000",List.of(need)).selections().getFirst().product().productId()).isEqualTo("z");
    }
    @Test void 空目录城市缺货混单位及未知规格分别保留原因(){var need=List.of(new Need("a",1,n("10"),"G"));assertThat(provider().lookup("110000",need).selections().getFirst().status()).isEqualTo("NO_PRODUCT");assertThat(provider(p("a","100","G","10",true,"310000",null)).lookup("110000",need).selections().getFirst().reason()).contains("城市");assertThat(provider(p("a","100","G","10",false,"110000",null)).lookup("110000",need).selections().getFirst().status()).isEqualTo("OUT_OF_STOCK");assertThat(provider(p("a","100","ML","10",true,"110000",null)).lookup("110000",need).selections().getFirst().status()).isEqualTo("UNIT_UNSUPPORTED");assertThat(provider(p("a",null,"G",null,true,"110000",null)).lookup("110000",need).selections().getFirst().status()).isEqualTo("QUOTE_UNKNOWN");}
    @Test void 非法配置与超范围报价明确失败不当免费商品(){var need=List.of(new Need("a",1,n("10"),"G"));for(String price:List.of("-1","0.001","10000000000000000"))assertThatThrownBy(()->provider(p("a","100","G",price,true,"110000",null)).lookup("110000",need)).isInstanceOf(IllegalStateException.class);assertThatThrownBy(()->provider(p("a","0","G","10",true,"110000",null)).lookup("110000",need)).isInstanceOf(IllegalStateException.class);}
    @Test void 同商品两份十克先合包未知独立估价不借用成交价(){var s=source("1",item("a","10","NEED_BUY","G",1L),item("b","10","NEED_BUY","G",1L));var view=ProductMatchCalculator.calculate(s,"110000",provider(p("a","100","G","10",true,"110000",null)).lookup("110000",ProductMatchCalculator.needs(s)));assertThat(view.purchaseGroups()).hasSize(1);assertThat(view.purchaseGroups().getFirst().packageCount()).isEqualTo("1");assertThat(view.costs().consumptionCost()).isEqualTo("2.00");assertThat(view.costs().purchaseOutlay()).isEqualTo("10.00");assertThat(view.costs().estimatedDemandCost()).isNull();assertThat(view.costs().budgetStatus()).isEqualTo("OVER_BUDGET");assertThat(view.lines()).hasSize(2);assertThat(view.lines().getFirst().product().purchaseUrl()).isNull();}
    @Test void 一百一十克包装两包显式估价及最后总额舍入(){var s=source("20",item("a","110","NEED_BUY","G",1L));var view=ProductMatchCalculator.calculate(s,"110000",provider(p("a","100","G","10",true,"110000","0.05")).lookup("110000",ProductMatchCalculator.needs(s)));assertThat(view.costs().consumptionCost()).isEqualTo("11.00");assertThat(view.costs().purchaseOutlay()).isEqualTo("20.00");assertThat(view.costs().estimatedDemandCost()).isEqualTo("5.50");var third=source(null,item("a","1","NEED_BUY","G",1L),item("b","1","NEED_BUY","G",1L));assertThat(ProductMatchCalculator.calculate(third,"110000",provider(p("a","3","G","1",true,"110000",null)).lookup("110000",ProductMatchCalculator.needs(third))).costs().consumptionCost()).isEqualTo("0.67");}
    @Test void 未知及未归一不送Provider足量为零部分匹配保留全行(){var s=source("100",item("a","10","NEED_BUY","G",1L),item("b",null,"QUANTITY_PENDING","G",1L),item("c","1","NEED_BUY","CUSTOM",1L),item("d","1","NEED_BUY","G",null),item("e",null,"HAVE_ENOUGH",null,null));var needs=ProductMatchCalculator.needs(s);assertThat(needs).hasSize(1);var v=ProductMatchCalculator.calculate(s,"110000",provider(p("a","100","G","10",true,"110000",null)).lookup("110000",needs));assertThat(v.matchingStatus()).isEqualTo("PARTIAL");assertThat(v.lines()).hasSize(5);assertThat(v.costs().consumptionCost()).isNull();assertThat(v.costs().knownSubtotal()).isEqualTo("1.00");assertThat(v.costs().unknownItemCount()).isEqualTo(3);assertThat(v.costs().budgetStatus()).isEqualTo("UNKNOWN");var enough=ProductMatchCalculator.calculate(source("1",item("e",null,"HAVE_ENOUGH",null,null)),"110000",new Offers("NOT_QUERIED",List.of()));assertThat(enough.matchingStatus()).isEqualTo("NOT_NEEDED");assertThat(enough.costs().estimatedDemandCost()).isEqualTo("0.00");}
    @Test void 金额和包数超列范围失败不截断(){var s=source(null,item("a","1000000000000000","NEED_BUY","G",1L));assertThatThrownBy(()->ProductMatchCalculator.calculate(s,"110000",provider(p("a","0.00000001","G","10",true,"110000",null)).lookup("110000",ProductMatchCalculator.needs(s)))).isInstanceOf(com.cooker.common.ApiException.class);}
    @Test void 严格城市UUID拒绝数字重复尾随和客户端报价(){String valid="{\"requestId\":\"00000000-0000-4000-8000-000000000001\",\"cityCode\":\"110000\"}";assertThat(ProductMatchRequest.parse(valid).cityCode()).isEqualTo("110000");for(String raw:List.of("{}","null",valid+"{}",valid.replace("\"110000\"","110000"),valid.replace("\"110000\"","\"11000\""),valid.replace("\"cityCode\":","\"price\":1,\"cityCode\":"),valid.replace("\"cityCode\":","\"cityCode\":\"310000\",\"cityCode\":")))assertThatThrownBy(()->ProductMatchRequest.parse(raw)).isInstanceOf(com.cooker.common.ApiException.class);}
}
